#!/usr/bin/env bash
# Checks every link from the R companion into the textbook
# (../chapters/chapter-NN.html#section-id) against the rendered book in docs/.
# The textbook's section ids are generated by Quarto from the heading text, so
# renaming a heading breaks the companion's links to it without any error;
# this check catches that. Run it after `quarto render`.
#
#   tools/links/check_companion_links.sh
#
# Exit 0 when every link resolves, 1 when any is broken, 2 when docs/ is missing.

cd "$(dirname "$0")/../.." || exit 2
[ -d docs/chapters ] || { echo "docs/chapters not found; render the textbook first."; exit 2; }

TOTAL=0
BROKEN=0
while IFS= read -r hit; do
  file=${hit%%:*}
  rest=${hit#*:}
  line=${rest%%:*}
  target=${rest#*:}
  target=${target#](../chapters/}
  target=${target%)}
  page=${target%%#*}
  anchor=""
  [[ "$target" == *"#"* ]] && anchor=${target#*#}
  TOTAL=$((TOTAL + 1))
  html="docs/chapters/$page"
  if [ ! -f "$html" ]; then
    echo "BROKEN $file:$line  $page (page not found)"
    BROKEN=$((BROKEN + 1))
  elif [ -n "$anchor" ] && ! grep -qF "id=\"$anchor\"" "$html"; then
    echo "BROKEN $file:$line  $page#$anchor (section not found; was the heading renamed?)"
    BROKEN=$((BROKEN + 1))
  fi
done < <(grep -noE '\]\(\.\./chapters/[^)]+\)' r_companion/*.qmd)

echo "Companion links into the textbook: $TOTAL checked, $BROKEN broken"
[ "$BROKEN" -eq 0 ]
